// Primary Function Template
template <typename T>
void log_value(T val) {
    /* Generic logging mechanism */
}

// Full Specialization for 'int'
// Syntax: template <> (empty parameter list)
template <>
void log_value<int>(int val) {
    /* Optimized integer handler */
    if (val < 0) { /* Error check */ }
}

// Full Specialization for 'const char*' (C-string)
template <>
void log_value<const char*>(const char* val) {
    /* Specific implementation for strings */
    if (val == nullptr) { /* Null check */ }
}
